-- =============================================================================
-- SWAPMART — initial schema (migration 001)
-- A Secure Peer-to-Peer Recommerce Marketplace for Consumer Electronics in
-- Tanzania. PostgreSQL 14+ (developed and tested on PostgreSQL 17).
--
-- Conventions
--   * Primary keys are UUIDs generated by the database (gen_random_uuid()).
--   * Every table carries created_at/updated_at timestamptz columns.
--   * Enum-like columns use TEXT + CHECK constraints generated from the shared
--     TypeScript enumerations so the database and the application agree.
--   * Monetary amounts are BIGINT whole Tanzanian shillings (never floating
--     point, which would introduce rounding errors).
--   * Deletion is soft for user-generated content (status columns, deleted_at)
--     so moderation and audit history is never silently destroyed.
--   * Device identifiers are stored twice: an AES-256-GCM ciphertext for
--     authorised display, and a keyed HMAC-SHA256 fingerprint used for
--     duplicate detection and uniqueness. The plaintext is never persisted and
--     never returned by the API.
-- =============================================================================

-- gen_random_uuid() is provided by PostgreSQL core (13+), so no extension is
-- required and the migration runs with ordinary (non-superuser) privileges on
-- managed PostgreSQL services.

-- -----------------------------------------------------------------------------
-- Shared triggers
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- -----------------------------------------------------------------------------
-- Reference data: categories and brands
-- -----------------------------------------------------------------------------
CREATE TABLE categories (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug          text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]{2,60}$'),
  name          text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 80),
  description   text NOT NULL DEFAULT '',
  icon          text NOT NULL DEFAULT 'box',
  sort_order    integer NOT NULL DEFAULT 100,
  is_active     boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER categories_updated_at BEFORE UPDATE ON categories FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE brands (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug          text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]{1,60}$'),
  name          text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),
  is_active     boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER brands_updated_at BEFORE UPDATE ON brands FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Accounts
-- -----------------------------------------------------------------------------
CREATE TABLE users (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email                 text NOT NULL,
  email_normalised      text GENERATED ALWAYS AS (lower(btrim(email))) STORED,
  email_verified_at     timestamptz,
  password_hash         text NOT NULL,
  password_changed_at   timestamptz NOT NULL DEFAULT now(),
  full_name             text NOT NULL CHECK (char_length(full_name) BETWEEN 2 AND 120),
  -- Privileged columns. Assignable only by administrator provisioning, never by
  -- a public endpoint or a user-editable profile form.
  role                  text NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  account_status        text NOT NULL DEFAULT 'active' CHECK (account_status IN ('active', 'restricted', 'suspended', 'deactivated')),
  status_reason         text,
  restricted_until      timestamptz,
  suspended_at          timestamptz,
  deactivated_at        timestamptz,
  identity_reviewed_at  timestamptz,
  identity_reviewed_by  uuid REFERENCES users(id) ON DELETE SET NULL,
  failed_login_count    integer NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
  locked_until          timestamptz,
  last_login_at         timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_email_unique UNIQUE (email_normalised),
  CONSTRAINT users_email_shape CHECK (email_normalised ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')
);
CREATE TRIGGER users_updated_at BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX users_role_status_idx ON users (role, account_status);
CREATE INDEX users_created_at_idx ON users (created_at DESC);

CREATE TABLE user_profiles (
  user_id             uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  display_name        text NOT NULL CHECK (char_length(display_name) BETWEEN 2 AND 80),
  bio                 text CHECK (bio IS NULL OR char_length(bio) <= 600),
  region              text,
  city                text,
  phone               text,
  phone_visible       boolean NOT NULL DEFAULT false,
  public_profile      boolean NOT NULL DEFAULT true,
  avatar_media_id     uuid,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER user_profiles_updated_at BEFORE UPDATE ON user_profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE sessions (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash    text NOT NULL UNIQUE,
  csrf_hash     text NOT NULL,
  ip_address    text,
  user_agent    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_seen_at  timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL,
  revoked_at    timestamptz,
  revoked_reason text
);
CREATE INDEX sessions_user_idx ON sessions (user_id, expires_at DESC);
CREATE INDEX sessions_expiry_idx ON sessions (expires_at) WHERE revoked_at IS NULL;

-- Verification / recovery tokens: only the hash is stored.
CREATE TABLE auth_tokens (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose       text NOT NULL CHECK (purpose IN ('email_verification', 'password_reset', 'email_change')),
  token_hash    text NOT NULL UNIQUE,
  expires_at    timestamptz NOT NULL,
  consumed_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  request_ip    text
);
CREATE INDEX auth_tokens_user_purpose_idx ON auth_tokens (user_id, purpose, expires_at DESC);

-- Development "log" email transport writes to this table so that verification
-- links are inspectable in local environments and in automated tests.
CREATE TABLE email_outbox (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  to_email      text NOT NULL,
  subject       text NOT NULL,
  body_text     text NOT NULL,
  template      text NOT NULL,
  status        text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sent', 'failed', 'logged')),
  transport     text NOT NULL,
  error         text,
  metadata      jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at    timestamptz NOT NULL DEFAULT now(),
  sent_at       timestamptz
);
CREATE INDEX email_outbox_created_idx ON email_outbox (created_at DESC);

-- -----------------------------------------------------------------------------
-- Media assets (device images, private verification evidence, dispute files)
-- -----------------------------------------------------------------------------
CREATE TABLE media_assets (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id       uuid REFERENCES users(id) ON DELETE SET NULL,
  purpose        text NOT NULL CHECK (purpose IN ('listing_image', 'evidence', 'dispute_attachment', 'avatar')),
  visibility     text NOT NULL CHECK (visibility IN ('public', 'private')),
  storage_driver text NOT NULL CHECK (storage_driver IN ('cloudinary', 'local')),
  storage_key    text NOT NULL,
  provider_meta  jsonb NOT NULL DEFAULT '{}'::jsonb,
  url            text,
  mime_type      text NOT NULL,
  byte_size      bigint NOT NULL CHECK (byte_size > 0),
  width          integer,
  height         integer,
  checksum_sha256 text NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  deleted_at     timestamptz,
  CONSTRAINT media_assets_key_unique UNIQUE (storage_driver, storage_key)
);
CREATE TRIGGER media_assets_updated_at BEFORE UPDATE ON media_assets FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX media_assets_owner_idx ON media_assets (owner_id, purpose, created_at DESC);
CREATE INDEX media_assets_checksum_idx ON media_assets (checksum_sha256);
CREATE INDEX media_assets_public_idx ON media_assets (purpose, created_at DESC) WHERE visibility = 'public' AND deleted_at IS NULL;

ALTER TABLE user_profiles
  ADD CONSTRAINT user_profiles_avatar_fk FOREIGN KEY (avatar_media_id) REFERENCES media_assets(id) ON DELETE SET NULL;

-- -----------------------------------------------------------------------------
-- Devices and listings
-- -----------------------------------------------------------------------------
CREATE TABLE devices (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id    uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
  brand_id       uuid REFERENCES brands(id) ON DELETE SET NULL,
  brand_name     text CHECK (brand_name IS NULL OR char_length(brand_name) <= 60),
  model          text NOT NULL CHECK (char_length(model) BETWEEN 1 AND 80),
  condition      text NOT NULL CHECK (condition IN ('new_sealed', 'like_new', 'excellent', 'good', 'fair', 'for_parts')),
  specs          jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by     uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT devices_brand_present CHECK (brand_id IS NOT NULL OR (brand_name IS NOT NULL AND btrim(brand_name) <> '')),
  CONSTRAINT devices_specs_is_object CHECK (jsonb_typeof(specs) = 'object')
);
CREATE TRIGGER devices_updated_at BEFORE UPDATE ON devices FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX devices_category_idx ON devices (category_id, created_at DESC);
CREATE INDEX devices_brand_idx ON devices (brand_id);
CREATE INDEX devices_model_trgm_idx ON devices (lower(model));

CREATE TABLE listings (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  device_id       uuid NOT NULL REFERENCES devices(id) ON DELETE RESTRICT,
  seller_id       uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  category_id     uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
  brand_id        uuid REFERENCES brands(id) ON DELETE SET NULL,
  title           text NOT NULL CHECK (char_length(title) BETWEEN 8 AND 120),
  slug            text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]{8,140}$'),
  description     text NOT NULL CHECK (char_length(description) BETWEEN 40 AND 4000),
  asking_price_tzs bigint NOT NULL CHECK (asking_price_tzs BETWEEN 1000 AND 500000000),
  negotiable      boolean NOT NULL DEFAULT true,
  exchange_allowed boolean NOT NULL DEFAULT true,
  condition       text NOT NULL CHECK (condition IN ('new_sealed', 'like_new', 'excellent', 'good', 'fair', 'for_parts')),
  region          text NOT NULL,
  city            text,
  status          text NOT NULL DEFAULT 'draft'
                  CHECK (status IN ('draft', 'submitted', 'checks_pending', 'flagged', 'under_review',
                                    'evidence_required', 'approved', 'rejected', 'suspended', 'withdrawn')),
  availability    text NOT NULL DEFAULT 'available'
                  CHECK (availability IN ('available', 'reserved', 'sold', 'inactive')),
  view_count      integer NOT NULL DEFAULT 0 CHECK (view_count >= 0),
  submitted_at    timestamptz,
  published_at    timestamptz,
  last_reviewed_at timestamptz,
  decided_at      timestamptz,
  decision_reason_code text,
  decision_reason_note text,
  review_priority text NOT NULL DEFAULT 'normal' CHECK (review_priority IN ('normal', 'high', 'urgent')),
  submission_round integer NOT NULL DEFAULT 0 CHECK (submission_round >= 0),
  -- Full-text index over seller-authored text. Brand, model and category are
  -- matched through their own indexed columns, so they are not duplicated here.
  search_document tsvector GENERATED ALWAYS AS (
    to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(description, ''))
  ) STORED,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  -- A listing may only be marked sold when it was approved and is not under
  -- moderation action: this blocks "sold" being used to hide a live problem.
  CONSTRAINT listings_availability_sold_requires_approval CHECK (
    availability <> 'sold' OR status IN ('approved', 'suspended')
  )
);
CREATE TRIGGER listings_updated_at BEFORE UPDATE ON listings FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE INDEX listings_public_idx ON listings (published_at DESC)
  WHERE status = 'approved' AND availability <> 'inactive' AND deleted_at IS NULL;
CREATE INDEX listings_seller_idx ON listings (seller_id, created_at DESC);
CREATE INDEX listings_moderation_queue_idx ON listings (review_priority DESC, submitted_at ASC)
  WHERE status IN ('submitted', 'checks_pending', 'flagged', 'under_review', 'evidence_required');
CREATE INDEX listings_status_idx ON listings (status, created_at DESC);
CREATE INDEX listings_category_price_idx ON listings (category_id, asking_price_tzs) WHERE status = 'approved';
CREATE INDEX listings_condition_idx ON listings (condition) WHERE status = 'approved';
CREATE INDEX listings_region_idx ON listings (region) WHERE status = 'approved';
CREATE INDEX listings_search_idx ON listings USING gin (search_document);

CREATE TABLE listing_images (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id     uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  media_asset_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,
  position       integer NOT NULL DEFAULT 0 CHECK (position >= 0),
  alt_text       text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT listing_images_unique_asset UNIQUE (listing_id, media_asset_id)
);
CREATE INDEX listing_images_listing_idx ON listing_images (listing_id, position DESC);

-- -----------------------------------------------------------------------------
-- Device identifiers: ciphertext + keyed fingerprint for duplicate detection
-- -----------------------------------------------------------------------------
CREATE TABLE device_identifiers (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  device_id      uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  listing_id     uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  owner_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind           text NOT NULL CHECK (kind IN ('imei', 'serial', 'meid', 'mac_address', 'model_number')),
  -- AES-256-GCM envelope: v1.iv.tag.ciphertext (base64url parts).
  value_encrypted text NOT NULL,
  -- HMAC-SHA256(normalised value). Enables uniqueness without decryption.
  fingerprint    text NOT NULL CHECK (char_length(fingerprint) = 64),
  last4          text NOT NULL CHECK (char_length(last4) BETWEEN 2 AND 4),
  masked         text NOT NULL,
  is_primary     boolean NOT NULL DEFAULT false,
  is_active      boolean NOT NULL DEFAULT false,
  activated_at   timestamptz,
  released_at    timestamptz,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT device_identifiers_listing_kind_unique UNIQUE (listing_id, kind)
);
CREATE TRIGGER device_identifiers_updated_at BEFORE UPDATE ON device_identifiers FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- The critical duplicate-prevention constraint: at most one *active* claim per
-- identifier fingerprint across the whole platform. Simultaneous submissions
-- are serialised by PostgreSQL and the loser receives a unique violation, which
-- the API converts into a moderator alert rather than a misleading error.
CREATE UNIQUE INDEX device_identifiers_active_fingerprint_idx
  ON device_identifiers (fingerprint) WHERE is_active;
CREATE INDEX device_identifiers_device_idx ON device_identifiers (device_id);
CREATE INDEX device_identifiers_listing_idx ON device_identifiers (listing_id);
CREATE INDEX device_identifiers_owner_idx ON device_identifiers (owner_id, created_at DESC);

-- Every attempt to claim an identifier is recorded, including rejected ones, so
-- repeated reuse attempts by the same account are visible to moderators.
CREATE TABLE identifier_conflicts (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fingerprint    text NOT NULL CHECK (char_length(fingerprint) = 64),
  kind           text NOT NULL,
  attempted_by   uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  attempted_listing_id uuid REFERENCES listings(id) ON DELETE SET NULL,
  existing_listing_id  uuid REFERENCES listings(id) ON DELETE SET NULL,
  existing_owner_id    uuid REFERENCES users(id) ON DELETE SET NULL,
  outcome        text NOT NULL CHECK (outcome IN ('blocked_published_listing', 'blocked_pending_review', 'blocked_released_history', 'allowed')),
  detail         text,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX identifier_conflicts_owner_idx ON identifier_conflicts (attempted_by, created_at DESC);
CREATE INDEX identifier_conflicts_created_idx ON identifier_conflicts (created_at DESC);

-- -----------------------------------------------------------------------------
-- Verification workflow
-- -----------------------------------------------------------------------------
CREATE TABLE device_verification_attempts (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  device_id           uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  listing_id          uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  attempt_number      integer NOT NULL CHECK (attempt_number > 0),
  outcome             text NOT NULL CHECK (outcome IN ('clean', 'flagged', 'needs_evidence', 'unavailable')),
  score               integer NOT NULL DEFAULT 0 CHECK (score BETWEEN 0 AND 100),
  flags               jsonb NOT NULL DEFAULT '[]'::jsonb,
  checks              jsonb NOT NULL DEFAULT '[]'::jsonb,
  external_check_status text NOT NULL DEFAULT 'not_configured'
                      CHECK (external_check_status IN ('not_configured', 'not_performed', 'clear', 'match', 'error', 'timeout')),
  external_provider   text,
  external_response   jsonb,
  external_checked_at timestamptz,
  engine_version      text NOT NULL DEFAULT '1.0.0',
  duration_ms         integer,
  created_at          timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT device_verification_attempt_unique UNIQUE (listing_id, attempt_number)
);
CREATE INDEX device_verification_attempts_listing_idx ON device_verification_attempts (listing_id, created_at DESC);
CREATE INDEX device_verification_attempts_outcome_idx ON device_verification_attempts (outcome, created_at DESC);

CREATE TABLE verification_evidence (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id     uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  device_id      uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  media_asset_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,
  uploaded_by    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind           text NOT NULL CHECK (kind IN ('proof_of_purchase', 'device_front', 'device_back', 'imei_screenshot',
                                               'serial_label', 'box_label', 'warranty_document', 'other')),
  note           text,
  -- Evidence a moderator explicitly asked for in a request_evidence decision.
  requested      boolean NOT NULL DEFAULT false,
  -- Never public: evidence is reachable by the owner and by administrators only,
  -- through an access-controlled media endpoint.
  created_at     timestamptz NOT NULL DEFAULT now(),
  deleted_at     timestamptz,
  CONSTRAINT verification_evidence_unique_asset UNIQUE (listing_id, media_asset_id)
);
CREATE INDEX verification_evidence_listing_idx ON verification_evidence (listing_id, created_at DESC);
CREATE INDEX verification_evidence_pending_idx ON verification_evidence (listing_id) WHERE deleted_at IS NULL;

-- Evidence items a moderator requested when asking for corrections.
CREATE TABLE evidence_requests (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id     uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  requested_by   uuid NOT NULL REFERENCES users(id) ON DELETE SET NULL,
  kind           text NOT NULL,
  note           text,
  fulfilled_at   timestamptz,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX evidence_requests_listing_idx ON evidence_requests (listing_id, created_at DESC);

-- Verification state-machine history (seller-visible, minus internal notes).
CREATE TABLE verification_events (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id     uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  device_id      uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  actor_id       uuid REFERENCES users(id) ON DELETE SET NULL,
  actor_role     text NOT NULL CHECK (actor_role IN ('user', 'admin', 'system')),
  action         text NOT NULL,
  from_status    text,
  to_status      text,
  reason_code    text,
  reason_note    text,
  visible_to_seller boolean NOT NULL DEFAULT true,
  metadata       jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX verification_events_listing_idx ON verification_events (listing_id, created_at ASC);

-- Automated duplicate / suspicious-submission alerts for moderator triage.
CREATE TABLE duplicate_alerts (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind               text NOT NULL CHECK (kind IN ('identifier_conflict', 'image_duplicate', 'title_similarity', 'rapid_resubmission')),
  severity           text NOT NULL DEFAULT 'warning' CHECK (severity IN ('info', 'warning', 'critical')),
  listing_id         uuid REFERENCES listings(id) ON DELETE CASCADE,
  related_listing_id uuid REFERENCES listings(id) ON DELETE SET NULL,
  device_id          uuid REFERENCES devices(id) ON DELETE CASCADE,
  fingerprint        text,
  detail             text NOT NULL,
  metadata           jsonb NOT NULL DEFAULT '{}'::jsonb,
  resolved_at        timestamptz,
  resolved_by        uuid REFERENCES users(id) ON DELETE SET NULL,
  resolution_note    text,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX duplicate_alerts_open_idx ON duplicate_alerts (severity DESC, created_at DESC) WHERE resolved_at IS NULL;
CREATE INDEX duplicate_alerts_listing_idx ON duplicate_alerts (listing_id, created_at DESC);

-- -----------------------------------------------------------------------------
-- Conversations, messages, listing questions
-- -----------------------------------------------------------------------------
CREATE TABLE conversations (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind             text NOT NULL DEFAULT 'listing_inquiry' CHECK (kind IN ('listing_inquiry', 'transaction', 'moderation')),
  listing_id       uuid REFERENCES listings(id) ON DELETE SET NULL,
  transaction_id   uuid,
  initiator_id     uuid REFERENCES users(id) ON DELETE SET NULL,
  status           text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'archived', 'locked')),
  subject          text,
  last_message_at  timestamptz,
  last_message_excerpt text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER conversations_updated_at BEFORE UPDATE ON conversations FOR EACH ROW EXECUTE FUNCTION set_updated_at();
-- One inquiry thread per (listing, buyer). Prevents duplicate threads and makes
-- the "message the seller" action idempotent.
CREATE UNIQUE INDEX conversations_listing_initiator_idx
  ON conversations (listing_id, initiator_id) WHERE kind = 'listing_inquiry' AND listing_id IS NOT NULL;
CREATE INDEX conversations_recent_idx ON conversations (last_message_at DESC NULLS LAST);

CREATE TABLE conversation_participants (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  user_id        uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role           text NOT NULL CHECK (role IN ('buyer', 'seller', 'moderator')),
  last_read_at   timestamptz,
  is_muted       boolean NOT NULL DEFAULT false,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT conversation_participants_unique UNIQUE (conversation_id, user_id)
);
CREATE INDEX conversation_participants_user_idx ON conversation_participants (user_id, conversation_id);

CREATE TABLE messages (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  sender_id       uuid REFERENCES users(id) ON DELETE SET NULL,
  body            text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 4000),
  state           text NOT NULL DEFAULT 'visible' CHECK (state IN ('visible', 'hidden', 'redacted')),
  -- System messages record state changes inside a thread (e.g. an exchange was
  -- accepted) so the conversation history stays coherent.
  is_system       boolean NOT NULL DEFAULT false,
  moderation_note text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  edited_at       timestamptz
);
CREATE INDEX messages_conversation_idx ON messages (conversation_id, created_at ASC);
CREATE INDEX messages_sender_idx ON messages (sender_id, created_at DESC);

CREATE TABLE listing_comments (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  author_id  uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  parent_id  uuid REFERENCES listing_comments(id) ON DELETE CASCADE,
  body       text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 2 AND 1200),
  state      text NOT NULL DEFAULT 'visible' CHECK (state IN ('visible', 'hidden', 'removed')),
  is_seller_answer boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE TRIGGER listing_comments_updated_at BEFORE UPDATE ON listing_comments FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX listing_comments_listing_idx ON listing_comments (listing_id, created_at ASC);
CREATE INDEX listing_comments_parent_idx ON listing_comments (parent_id);

-- -----------------------------------------------------------------------------
-- Exchange requests and transactions
-- -----------------------------------------------------------------------------
CREATE TABLE exchange_requests (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id            uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  offered_listing_id    uuid REFERENCES listings(id) ON DELETE SET NULL,
  requester_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  recipient_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  parent_request_id     uuid REFERENCES exchange_requests(id) ON DELETE SET NULL,
  message               text NOT NULL CHECK (char_length(btrim(message)) BETWEEN 10 AND 4000),
  price_difference_tzs  bigint NOT NULL DEFAULT 0 CHECK (price_difference_tzs BETWEEN -500000000 AND 500000000),
  status                text NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'accepted', 'rejected', 'countered', 'cancelled', 'completed', 'expired')),
  responded_at          timestamptz,
  expires_at            timestamptz,
  transaction_id        uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT exchange_not_self CHECK (requester_id <> recipient_id)
);
CREATE TRIGGER exchange_requests_updated_at BEFORE UPDATE ON exchange_requests FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX exchange_requests_recipient_idx ON exchange_requests (recipient_id, status, created_at DESC);
CREATE INDEX exchange_requests_requester_idx ON exchange_requests (requester_id, status, created_at DESC);
CREATE INDEX exchange_requests_listing_idx ON exchange_requests (listing_id, status);
-- A user may only have one open proposal per (target listing, offered listing).
CREATE UNIQUE INDEX exchange_requests_open_unique_idx
  ON exchange_requests (listing_id, requester_id, offered_listing_id)
  WHERE status = 'pending';

CREATE TABLE transactions (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reference        text NOT NULL UNIQUE,
  type             text NOT NULL DEFAULT 'purchase' CHECK (type IN ('purchase', 'exchange')),
  status           text NOT NULL DEFAULT 'initiated'
                   CHECK (status IN ('initiated', 'negotiating', 'agreed', 'completed', 'cancelled', 'disputed')),
  listing_id       uuid NOT NULL REFERENCES listings(id) ON DELETE RESTRICT,
  seller_id        uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  buyer_id         uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  exchange_request_id uuid REFERENCES exchange_requests(id) ON DELETE SET NULL,
  offered_listing_id  uuid REFERENCES listings(id) ON DELETE SET NULL,
  agreed_amount_tzs bigint CHECK (agreed_amount_tzs IS NULL OR agreed_amount_tzs BETWEEN 0 AND 500000000),
  -- SWAPMART does not process payments in this version: this column records the
  -- parties' own note about how/where settlement is expected to happen.
  settlement_note  text,
  created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  completed_at     timestamptz,
  cancelled_at     timestamptz,
  cancel_reason    text,
  CONSTRAINT transactions_parties_differ CHECK (buyer_id <> seller_id)
);
CREATE TRIGGER transactions_updated_at BEFORE UPDATE ON transactions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX transactions_buyer_idx ON transactions (buyer_id, created_at DESC);
CREATE INDEX transactions_seller_idx ON transactions (seller_id, created_at DESC);
CREATE INDEX transactions_status_idx ON transactions (status, created_at DESC);
CREATE INDEX transactions_listing_idx ON transactions (listing_id);

ALTER TABLE conversations
  ADD CONSTRAINT conversations_transaction_fk FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE SET NULL;
ALTER TABLE exchange_requests
  ADD CONSTRAINT exchange_requests_transaction_fk FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE SET NULL;

CREATE TABLE transaction_status_history (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  transaction_id uuid NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
  from_status    text,
  to_status      text NOT NULL,
  actor_id       uuid REFERENCES users(id) ON DELETE SET NULL,
  actor_role     text NOT NULL DEFAULT 'user' CHECK (actor_role IN ('user', 'admin', 'system')),
  note           text,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX transaction_status_history_idx ON transaction_status_history (transaction_id, created_at ASC);

-- -----------------------------------------------------------------------------
-- Saved listings, notifications
-- -----------------------------------------------------------------------------
CREATE TABLE saved_listings (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  note       text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT saved_listings_unique UNIQUE (user_id, listing_id)
);
CREATE INDEX saved_listings_user_idx ON saved_listings (user_id, created_at DESC);

CREATE TABLE notifications (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type        text NOT NULL,
  title       text NOT NULL,
  body        text NOT NULL DEFAULT '',
  link_url    text,
  entity_type text,
  entity_id   uuid,
  read_at     timestamptz,
  -- When an email was also queued for this notification.
  emailed_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX notifications_user_idx ON notifications (user_id, created_at DESC);
CREATE INDEX notifications_unread_idx ON notifications (user_id) WHERE read_at IS NULL;

-- -----------------------------------------------------------------------------
-- Trust & safety: reports, disputes
-- -----------------------------------------------------------------------------
CREATE TABLE reports (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reference       text NOT NULL UNIQUE,
  reporter_id     uuid REFERENCES users(id) ON DELETE SET NULL,
  category        text NOT NULL CHECK (category IN ('suspected_stolen_device', 'fraudulent_seller', 'fraudulent_buyer',
                                                    'misleading_description', 'counterfeit_device', 'inappropriate_message',
                                                    'spam_or_duplicate_listing', 'harassment', 'other')),
  description     text NOT NULL CHECK (char_length(btrim(description)) BETWEEN 20 AND 3000),
  listing_id      uuid REFERENCES listings(id) ON DELETE SET NULL,
  reported_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  message_id      uuid REFERENCES messages(id) ON DELETE SET NULL,
  transaction_id  uuid REFERENCES transactions(id) ON DELETE SET NULL,
  status          text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'under_review', 'escalated', 'resolved', 'dismissed')),
  priority        text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  assigned_admin_id uuid REFERENCES users(id) ON DELETE SET NULL,
  resolution      text,
  resolved_at     timestamptz,
  resolved_by     uuid REFERENCES users(id) ON DELETE SET NULL,
  contact_consent boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  -- Reports are never deleted: closure states are explicit.
  closed_at       timestamptz
);
CREATE TRIGGER reports_updated_at BEFORE UPDATE ON reports FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX reports_status_idx ON reports (status, priority DESC, created_at DESC);
CREATE INDEX reports_listing_idx ON reports (listing_id);
CREATE INDEX reports_reported_user_idx ON reports (reported_user_id);
CREATE INDEX reports_reporter_idx ON reports (reporter_id, created_at DESC);

CREATE TABLE report_notes (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  report_id  uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,
  author_id  uuid REFERENCES users(id) ON DELETE SET NULL,
  author_role text NOT NULL DEFAULT 'admin' CHECK (author_role IN ('admin', 'system', 'user')),
  body       text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 2 AND 2000),
  -- moderator_note = internal only; reporter_visible = shared with the reporter.
  visibility text NOT NULL DEFAULT 'moderator_note' CHECK (visibility IN ('moderator_note', 'reporter_visible')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX report_notes_report_idx ON report_notes (report_id, created_at ASC);

CREATE TABLE disputes (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reference       text NOT NULL UNIQUE,
  transaction_id  uuid NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
  opened_by       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  counterparty_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  category        text NOT NULL CHECK (category IN ('item_not_as_described', 'device_not_delivered', 'exchange_not_completed',
                                                    'unresponsive_party', 'suspected_fraud', 'payment_disagreement', 'other')),
  description     text NOT NULL CHECK (char_length(btrim(description)) BETWEEN 20 AND 3000),
  status          text NOT NULL DEFAULT 'open'
                  CHECK (status IN ('open', 'investigating', 'awaiting_parties', 'escalated', 'resolved', 'closed')),
  assigned_admin_id uuid REFERENCES users(id) ON DELETE SET NULL,
  resolution      text,
  resolved_at     timestamptz,
  resolved_by     uuid REFERENCES users(id) ON DELETE SET NULL,
  related_report_id uuid REFERENCES reports(id) ON DELETE SET NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  closed_at       timestamptz,
  CONSTRAINT disputes_parties_differ CHECK (opened_by <> counterparty_id)
);
CREATE TRIGGER disputes_updated_at BEFORE UPDATE ON disputes FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX disputes_status_idx ON disputes (status, created_at DESC);
CREATE INDEX disputes_transaction_idx ON disputes (transaction_id);
CREATE INDEX disputes_opened_by_idx ON disputes (opened_by, created_at DESC);
CREATE INDEX disputes_counterparty_idx ON disputes (counterparty_id, created_at DESC);

CREATE TABLE dispute_messages (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  dispute_id   uuid NOT NULL REFERENCES disputes(id) ON DELETE CASCADE,
  author_id    uuid REFERENCES users(id) ON DELETE SET NULL,
  author_role  text NOT NULL CHECK (author_role IN ('user', 'admin', 'system')),
  body         text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 2 AND 2000),
  -- participants: visible to both parties + administrators.
  -- admins_only: internal moderation notes.
  visibility   text NOT NULL DEFAULT 'participants' CHECK (visibility IN ('participants', 'admins_only')),
  attachment_media_id uuid REFERENCES media_assets(id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX dispute_messages_dispute_idx ON dispute_messages (dispute_id, created_at ASC);

-- -----------------------------------------------------------------------------
-- Moderation and audit trail
-- -----------------------------------------------------------------------------
CREATE TABLE moderation_actions (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id    uuid REFERENCES users(id) ON DELETE SET NULL,
  actor_role  text NOT NULL CHECK (actor_role IN ('admin', 'system')),
  action      text NOT NULL,
  entity_type text NOT NULL,
  entity_id   uuid NOT NULL,
  from_status text,
  to_status   text,
  reason_code text,
  reason_note text,
  metadata    jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX moderation_actions_entity_idx ON moderation_actions (entity_type, entity_id, created_at DESC);
CREATE INDEX moderation_actions_actor_idx ON moderation_actions (actor_id, created_at DESC);
CREATE INDEX moderation_actions_action_idx ON moderation_actions (action, created_at DESC);

-- General notes attached to any moderated entity (internal by default).
CREATE TABLE moderation_notes (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type text NOT NULL,
  entity_id   uuid NOT NULL,
  author_id   uuid REFERENCES users(id) ON DELETE SET NULL,
  body        text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 2 AND 2000),
  visibility  text NOT NULL DEFAULT 'moderator_note' CHECK (visibility IN ('moderator_note', 'user_visible')),
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX moderation_notes_entity_idx ON moderation_notes (entity_type, entity_id, created_at DESC);

CREATE TABLE audit_logs (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id    uuid REFERENCES users(id) ON DELETE SET NULL,
  actor_role  text NOT NULL DEFAULT 'anonymous' CHECK (actor_role IN ('anonymous', 'user', 'admin', 'system')),
  action      text NOT NULL,
  entity_type text NOT NULL,
  entity_id   uuid,
  outcome     text NOT NULL DEFAULT 'success' CHECK (outcome IN ('success', 'failure', 'denied')),
  ip_address  text,
  user_agent  text,
  request_id  text,
  metadata    jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_created_idx ON audit_logs (created_at DESC);
CREATE INDEX audit_logs_actor_idx ON audit_logs (actor_id, created_at DESC);
CREATE INDEX audit_logs_entity_idx ON audit_logs (entity_type, entity_id, created_at DESC);
CREATE INDEX audit_logs_action_idx ON audit_logs (action, created_at DESC);

-- -----------------------------------------------------------------------------
-- Reference sequences for human-readable references (RPT-2026-000123)
-- -----------------------------------------------------------------------------
CREATE TABLE reference_counters (
  scope       text PRIMARY KEY,
  next_value  bigint NOT NULL DEFAULT 1 CHECK (next_value > 0)
);

CREATE OR REPLACE FUNCTION next_reference(prefix text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  current_value bigint;
BEGIN
  INSERT INTO reference_counters (scope, next_value) VALUES (prefix, 2)
  ON CONFLICT (scope) DO UPDATE SET next_value = reference_counters.next_value + 1
  RETURNING next_value - 1 INTO current_value;
  RETURN format('%s-%s-%s', prefix, to_char(now(), 'YYYY'), lpad(current_value::text, 6, '0'));
END $$;

-- -----------------------------------------------------------------------------
-- Derived helper views used by dashboards (statistics come from real queries)
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW listing_moderation_queue AS
SELECT l.id, l.title, l.status, l.review_priority, l.submitted_at, l.seller_id, l.category_id, l.asking_price_tzs
FROM listings l
WHERE l.status IN ('submitted', 'checks_pending', 'flagged', 'under_review', 'evidence_required')
  AND l.deleted_at IS NULL;

CREATE OR REPLACE VIEW public_listing_cards AS
SELECT l.id, l.title, l.slug, l.asking_price_tzs, l.condition, l.region, l.city, l.published_at, l.seller_id,
       l.category_id, l.brand_id, l.exchange_allowed, l.availability
FROM listings l
WHERE l.status = 'approved' AND l.availability <> 'inactive' AND l.deleted_at IS NULL;
